<script setup lang="ts">
import {entryDisplayName as localizedEntryName} from './runtime-presentation'

import { i18n as controlI18n } from '../app/i18n'
const { t: controlText } = controlI18n.global

import MapFieldPicker from "./map-selection/MapFieldPicker.vue"
import {computed,ref} from 'vue'
import type {RoomCommand,RoomView} from '../online/protocol'
import type {GmSpellFact,GmSpellChoice} from '../persistence/gm-spell-choice-schema'
import {G_RULES,G_ILLUSIONS} from '../core/gm-spell-rules'
import {gEntity} from '../core/gm-spell-world'
import GmSpellFields from './GmSpellFields.vue'
const props=defineProps<{view:RoomView;busy:boolean}>(),emit=defineEmits<{command:[RoomCommand]}>()
const a=computed(()=>props.view.world?.adventures[0]),scene=computed(()=>a.value?.scenes.find(s=>s.id===a.value?.activeSceneId))
const entities=computed(()=>{const w=props.view.world,v=a.value;if(!w||!v)return [];const rows=[...scene.value?.tokens??[],...scene.value?.defeatedTokens??[]].map(t=>{const e=gEntity(w,v,t.characterId??t.npcId??t.actorId??t.id);return{id:e.entity?.id??t.id,name:e.entity?.name??t.name}});return [...rows,...v.m3?.entities.filter(o=>o.enabled).map(o=>({id:o.id,name:o.name}))??[],...v.m1Utility?.corpses.filter(c=>c.dead).map(c=>({id:c.id,name:'遗骸 · '+gEntity(w,v,c.id).entity?.name}))??[]]})
const target=ref(''),observer=ref(''),note=ref(''),kind=ref<GmSpellFact['kind']>('creature'),mouth=ref(false),willing=ref(false),tiny=ref(false),known=ref(false),locked=ref(false),magical=ref(false),understands=ref(false),weight=ref(0),value=ref(0),material=ref(''),inventory=ref('')
const items=computed(()=>props.view.world?.characters.flatMap(c=>c.inventory.filter(i=>i.quantity>0).map(i=>({id:i.instanceId,owner:c.id,name:c.build.name+' · '+i.itemId+' ×'+i.quantity})))??[])
function fact(){const item=items.value.find(i=>i.id===inventory.value);emit('command',{kind:'spell-gm-fact',fact:{entityId:kind.value==='material'?(item?.id??target.value):target.value,sceneId:scene.value!.id,kind:kind.value,note:note.value,observerId:observer.value||undefined,mouthIntact:mouth.value,willing:willing.value,tiny:tiny.value,knowsTarget:known.value,locked:locked.value,magical:magical.value,understands:understands.value,weight:weight.value,valueGP:value.value,material:material.value||undefined,inventoryOwnerId:item?.owner,inventoryInstanceId:item?.id}})}
const selected=ref(''),active=computed(()=>props.view.gmSpells?.find(r=>r.id===selected.value)),actor=ref(''),object=ref(''),text=ref(''),words=ref(0),operation=ref<'move'|'operate'|'aura'|'switch'|'probe'|'resist-probe'|'reply'|'communicate'|'end'>('communicate'),mode=ref<'sight'|'hearing'>('sight'),x=ref(0),y=ref(0),height=ref(0)
function use(){if(!active.value)return;emit('command',{kind:'spell-gm-use',requestId:active.value.id,action:{operation:operation.value,receipt:crypto.randomUUID(),actorId:actor.value||active.value.characterId,objectId:object.value||undefined,point:['move','operate'].includes(operation.value)?{x:x.value,y:y.value,height:height.value}:undefined,mode:mode.value,text:text.value,wordCount:words.value}})}
const npc=ref(''),ability=ref(''),choice=ref<GmSpellChoice>({}),npcAbilities=computed(()=>{const w=props.view.world,v=a.value;return w&&v?gEntity(w,v,npc.value).entity?.body?.abilities?.filter(b=>b.spellId&&G_RULES[b.spellId]):[]}),spell=computed(()=>npcAbilities.value?.find(b=>b.id===ability.value)?.spellId)
</script>
<template>
 <details v-if="view.self.role==='gm'&&view.world" class="room-card g-tools"><summary>{{ controlText('operations.gCategorySpellsRulesFactsAndOngoingOperations') }}</summary>
  <p class="muted">{{ controlText('adjudication.registerActualObjectsWithSceneSpatialToolsThis') }}</p>
  <details><summary>{{ controlText('operations.registerTargetMaterialFacts') }}</summary><div class="g-grid"><label>{{ controlText('field.entity') }}<MapFieldPicker kind="entity"><select v-model="target"><option value="">{{ controlText('game.choose') }}</option><option v-for="e in entities" :key="e.id" :value="e.id">{{localizedEntryName(e)}} · {{e.id}}</option></select></MapFieldPicker></label><label>{{ controlText('field.factCategory') }}<select v-model="kind"><option value="creature">{{ controlText('operations.creature') }}</option><option value="corpse">{{ controlText('operations.remains') }}</option><option value="object">{{ controlText('domain.object') }}</option><option value="location">{{ controlText('operations.location') }}</option><option value="material">{{ controlText('domain.material') }}</option></select></label><label>{{ controlText('field.relationshipObserverOptional') }}<select v-model="observer"><option value="">{{ controlText('operations.generalFact') }}</option><option v-for="e in entities" :key="e.id" :value="e.id">{{localizedEntryName(e)}}</option></select></label></div>
   <div class="g-grid"><label><input v-model="mouth" type="checkbox" />{{ controlText('field.stillHasAMouth') }}</label><label><input v-model="willing" type="checkbox" />{{ controlText('field.willing') }}</label><label><input v-model="tiny" type="checkbox" />{{ controlText('domain.tiny') }}</label><label><input v-model="known" type="checkbox" />{{ controlText('field.familiarWithTarget') }}</label><label><input v-model="locked" type="checkbox" />{{ controlText('field.locked') }}</label><label><input v-model="magical" type="checkbox" />{{ controlText('field.magicalObject') }}</label><label><input v-model="understands" type="checkbox" />{{ controlText('field.languageTelepathicComprehensionEligibility') }}</label></div>
   <div v-if="kind==='material'" class="g-grid"><label>{{ controlText('field.actualInventoryMaterial') }}<select v-model="inventory"><option value="">{{ controlText('operations.useObjectBoundToSelectedNpc') }}</option><option v-for="i in items" :key="i.id" :value="i.id">{{localizedEntryName(i)}} · {{i.id}}</option></select></label><label>{{ controlText('domain.materialType') }}<input v-model="material" :placeholder="controlText('field.pearlLeadInkDivinationTokensSensoryFocus')" /></label><label>{{ controlText('domain.valueGP') }}<input v-model.number="value" type="number" min="0" /></label></div>
   <label>{{ controlText('field.verificationBasis') }}<input v-model="note" maxlength="2000" /></label><button :disabled="busy||!note.trim()||!scene" @click="fact">{{ controlText('operations.saveGmFacts') }}</button>
   <p v-for="f in a?.gmSpellFacts" :key="f.entityId+(f.observerId??'')" class="muted">{{f.entityId}} · {{f.kind}} · {{f.note}}</p>
  </details>
  <details><summary>{{ controlText('operations.ordinaryNpcExplorationCasting') }}</summary><div class="g-grid"><label>{{ controlText('field.actualNpc') }}<select v-model="npc"><option value="">{{ controlText('game.choose') }}</option><option v-for="e in entities" :key="e.id" :value="e.id">{{localizedEntryName(e)}}</option></select></label><label>{{ controlText('domain.actualAbility') }}<select v-model="ability"><option value="">{{ controlText('game.choose') }}</option><option v-for="b in npcAbilities" :key="b.id" :value="b.id">{{localizedEntryName(b)}}</option></select></label></div><GmSpellFields v-model="choice" :spell-id="spell" :targets="entities" /><button :disabled="busy||!spell||!note.trim()" @click="emit('command',{kind:'spell-gm-npc-cast',npcId:npc,abilityId:ability,targetIds:choice.subjectId?[choice.subjectId]:[npc],choice,note,confirmed:true})">{{ controlText('operations.confirmCastingCompletedAndSubmitForReview') }}</button></details>
  <label>{{ controlText('domain.castInstances') }}<select v-model="selected" :aria-label="controlText('domain.castInstances')"><option value="">{{ controlText('game.choose') }}</option><option v-for="r in view.gmSpells?.filter(r=>r.status!=='canceled')" :key="r.id" :value="r.id">{{localizedEntryName(r)}} · {{r.status}} · {{r.questionIndex}}</option></select></label>
  <template v-if="active"><button :disabled="busy||!note.trim()" @click="emit('command',{kind:'spell-gm-refresh',requestId:active.id,note})">{{ controlText('operations.recheckOriginalRequestAgainstCurrentConditions') }}</button>
   <div class="g-grid"><label>{{ controlText('field.actualOperatorObserver') }}<MapFieldPicker kind="entity"><select v-model="actor"><option value="">{{ controlText('operations.originalCaster') }}</option><option v-for="e in entities" :key="e.id" :value="e.id">{{localizedEntryName(e)}}</option></select></MapFieldPicker></label><label>{{ controlText('field.ongoingOperation') }}<select v-model="operation"><option value="communicate">{{ controlText('operations.gmSuppliesKnowableInformation') }}</option><option value="move">{{ controlText('operations.magicActionToMoveHandImage') }}</option><option value="operate">{{ controlText('operations.magicActionToManipulateExistingObject') }}</option><option value="aura">{{ controlText('operations.magicActionToObserveAurasReadThoughts') }}</option><option value="switch">{{ controlText('operations.bonusActionToSwitchSensor') }}</option><option value="probe">{{ controlText('operations.followUpMagicActionToProbeDeeper') }}</option><option value="resist-probe">{{ controlText('operations.targetUsesArcanaActionToEscapeProbing') }}</option><option value="reply">{{ controlText('operations.recipientSSingleReply') }}</option><option value="end">{{ controlText('operations.endThisOngoingInstance') }}</option></select></label><label>{{ controlText('field.actualObjectId') }}<input v-model="object" /></label><label>{{ controlText('field.sightHearing') }}<select v-model="mode"><option value="sight">{{ controlText('domain.visual') }}</option><option value="hearing">{{ controlText('domain.auditory') }}</option></select></label><label>X<input v-model.number="x" type="number" min="0" max="79" /></label><label>Y<input v-model.number="y" type="number" min="0" max="79" /></label><label>{{ controlText('field.height') }}<input v-model.number="height" type="number" /></label><label>{{ controlText('field.messageWordCount') }}<input v-model.number="words" type="number" min="0" max="25" /></label></div><label>{{ controlText('field.contentVerificationBasis') }}<textarea v-model="text" maxlength="2000" /></label>
   <button :disabled="busy||active.status!=='published'||!text.trim()" @click="use">{{ controlText('operations.confirmOngoingOperation') }}</button>
   <div v-if="G_ILLUSIONS.includes(active.spellId)" class="inline"><button :disabled="busy||!actor||!text.trim()" @click="emit('command',{kind:'spell-gm-observe',requestId:active.id,observerId:actor,method:'study',note:text})">{{ controlText('operations.observerTakesStudyAction') }}</button><button :disabled="busy||!actor||!text.trim()" @click="emit('command',{kind:'spell-gm-observe',requestId:active.id,observerId:actor,method:'physical',note:text})">{{ controlText('operations.confirmActualContact') }}</button><button :disabled="busy||!actor||!text.trim()" @click="emit('command',{kind:'spell-gm-observe',requestId:active.id,observerId:actor,method:'gm',note:text})">{{ controlText('operations.gmRecordsOtherEvidenceOfDetection') }}</button></div>
   <p v-for="o in active.observations" :key="o.observerId">{{o.observerId}} · {{o.recognized?controlText('expressionOne.detected'):controlText('expressionOne.notDetected')}} · {{o.text}}</p>
  </template>
 </details>
</template>
<style scoped>.g-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:.5rem}.g-tools input,.g-tools select,.g-tools textarea{max-width:100%;min-width:0}.g-tools p{overflow-wrap:anywhere}.g-tools details{margin-block:.6rem}</style>
